            sys.stderr.write("invalid next link structure\n")
            sys.exit(2)
        if not isinstance(raw, str):
            sys.stderr.write("invalid next link type\n")
            sys.exit(2)
        if len(raw) == 0:
            sys.stderr.write("empty next link\n")
            sys.exit(2)
