        curpage = first // size + 1
        if curpage < need:
            first = first + size
            current = base + "/api/kc/users?first=" + str(first) + "&max=" + str(size)
            if current in seen:
                sys.stderr.write("pagination loop detected\n")
                sys.exit(2)
            continue
