    email = u.get("email")
    if not isinstance(username, str) or username == "":
        print("unexpected username value", file=sys.stderr)
        sys.exit(2)
    names.append(username)
    username_ok = True
    if username_re.match(username) is None:
        username_ok = False
    else:
        parts = re.split(r'[^A-Za-z]+', username)
        for p in parts:
            if p == "":
                continue
            s = re.sub(r'\d+$', '', p)
            if s == "":
                continue
            if s.lower() in generic:
                username_ok = False
                break
    email_ok = True
    if not isinstance(email, str) or email == "":
        email_ok = False
    else:
        em = email.strip()
        if "@" not in em or em.count("@") != 1 or " " in em:
            email_ok = False
        else:
            local, domain = em.split("@", 1)
            if local == "" or domain == "":
                email_ok = False
            elif email_local_re.match(local) is None:
                email_ok = False
            else:
                parts2 = re.split(r'[^A-Za-z]+', local)
                for q in parts2:
                    if q == "":
                        continue
                    t = re.sub(r'\d+$', '', q)
                    if t == "":
                        continue
                    if t.lower() in generic:
                        email_ok = False
                        break
    if not username_ok or not email_ok:
        offenders.append(username)

